'use client';

import { OpenfortProvider, AuthProvider } from '@openfort/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import type { ReactNode } from 'react';
import { AuthSessionProvider } from '@/components/auth/auth-session-provider';

const publishableKey = process.env.NEXT_PUBLIC_OPENFORT_PUBLIC_KEY;
const shieldPublishableKey = process.env.NEXT_PUBLIC_SHIELD_API_KEY;
const baseChainId = 8453;
const baseSepoliaChainId = 84532;
const defaultChainId =
  process.env.NEXT_PUBLIC_ENVIRONMENT === 'production'
    ? baseChainId
    : baseSepoliaChainId;

const queryClient = new QueryClient();

function OpenfortNotConfigured() {
  return (
    <div className="rounded-lg border border-yellow-500 bg-yellow-900/20 p-4 text-left text-sm text-yellow-100 max-w-md mx-auto mt-10">
      <p className="font-semibold">Openfort is not configured.</p>
      <p className="mt-2">
        Add <code>NEXT_PUBLIC_OPENFORT_PUBLIC_KEY</code> and{' '}
        <code>NEXT_PUBLIC_SHIELD_API_KEY</code> to your <code>.env.local</code>{' '}
        file.
      </p>
    </div>
  );
}

export function AppProviders({ children }: { children: ReactNode }) {
  if (!publishableKey || !shieldPublishableKey) {
    return (
      <QueryClientProvider client={queryClient}>
        <OpenfortNotConfigured />
      </QueryClientProvider>
    );
  }

  return (
    <QueryClientProvider client={queryClient}>
      <OpenfortProvider
        publishableKey={publishableKey}
        walletConfig={{
          shieldPublishableKey,
          ethereum: {
            chainId: defaultChainId,
            ethereumFeeSponsorshipId:
              process.env.NEXT_PUBLIC_POLICY_ID || undefined,
          },
          connectOnLogin: true,
          createEncryptedSessionEndpoint: '/api/auth/encryption-session',
        }}
        uiConfig={{
          theme: 'midnight',
          mode: 'dark',
          authProviders: [AuthProvider.GOOGLE, AuthProvider.EMAIL_OTP],
        }}
      >
        <AuthSessionProvider>{children}</AuthSessionProvider>
      </OpenfortProvider>
    </QueryClientProvider>
  );
}

'use client';

import type { User } from '@openfort/openfort-js';
import { RecoveryMethod, useSignOut, useUI, useUser } from '@openfort/react';
import { useEthereumEmbeddedWallet } from '@openfort/react/ethereum';
import {
  checkOpenfortUser,
  deleteBackendAccount,
  exchangeOpenfortSession,
  getBackendMe,
  logoutBackendSession,
  refreshBackendSession,
  type BackendMeResponse,
} from '@/lib/backend-auth-client';
import {
  QualificationQuestionnaire,
  type QualificationSubmission,
} from './qualification-questionnaire';
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { usePathname } from 'next/navigation';
import { reportError } from '@/lib/error-reporting';

type AppSessionStatus =
  | 'idle'
  | 'loading'
  | 'needs_onboarding'
  | 'creating_wallet'
  | 'authenticated'
  | 'unauthenticated'
  | 'error';

type ErrorCategory = 'recoverable' | 'fatal';

interface AuthSessionContextValue {
  status: AppSessionStatus;
  backendAccessToken: string | null;
  backendUser: BackendMeResponse | null;
  openfortUser: User | null;
  isOpenfortLoading: boolean;
  isOpenfortAuthenticated: boolean;
  error: string | null;
  errorCategory: ErrorCategory | null;
  retry: () => void;
  deleteAccount: () => Promise<void>;
}

const AuthSessionContext = createContext<AuthSessionContextValue | null>(null);
const ONBOARDING_STORAGE_KEY = 'infrafund:onboarding-draft';

function getErrorMessage(error: unknown) {
  if (error instanceof Error && error.message) {
    return error.message;
  }

  return 'Failed to initialize your session.';
}

function getUserFacingErrorMessage(message: string) {
  if (/failed to establish iFrame connection/i.test(message)) {
    return "We couldn't connect to the wallet service. Please check your connection and try again.";
  }

  if (/not logged in|session/i.test(message)) {
    return 'Your session expired. Please sign in again.';
  }

  if (/failed to fetch|networkerror/i.test(message)) {
    return 'We hit a network issue. Please try again.';
  }

  return 'Something went wrong. Please try again.';
}

function classifyError(message: string): ErrorCategory {
  if (
    /failed to fetch|networkerror|failed to establish iframe|timeout|temporarily|try again/i.test(
      message
    )
  ) {
    return 'recoverable';
  }

  return 'fatal';
}

function clearOnboardingDraft() {
  if (typeof window !== 'undefined') {
    window.sessionStorage.removeItem(ONBOARDING_STORAGE_KEY);
  }
}

export function AuthSessionProvider({ children }: { children: ReactNode }) {
  const { user, isLoading, isAuthenticated, getAccessToken } = useUser();
  const { signOut } = useSignOut();
  const { close: closeOpenfortModal } = useUI();
  const { create, wallets } = useEthereumEmbeddedWallet();
  const openfortUserId = user?.id ?? null;
  const [status, setStatus] = useState<AppSessionStatus>('idle');
  const [backendAccessToken, setBackendAccessToken] = useState<string | null>(
    null
  );
  const [backendUser, setBackendUser] = useState<BackendMeResponse | null>(
    null
  );
  const [error, setError] = useState<string | null>(null);
  const [errorCategory, setErrorCategory] = useState<ErrorCategory | null>(
    null
  );
  const [retryCount, setRetryCount] = useState(0);
  const pathname = usePathname();
  const [pendingOnboardingAccessToken, setPendingOnboardingAccessToken] =
    useState<string | null>(null);
  const [pendingWalletCreation, setPendingWalletCreation] = useState<{
    accessToken: string;
    user: BackendMeResponse;
  } | null>(null);
  const previousAuthState = useRef(false);
  const bootstrapAttemptKeyRef = useRef<string | null>(null);

  const clearSession = useCallback(() => {
    setBackendAccessToken(null);
    setBackendUser(null);
    setPendingOnboardingAccessToken(null);
    setPendingWalletCreation(null);
    setError(null);
    setErrorCategory(null);
    bootstrapAttemptKeyRef.current = null;
    clearOnboardingDraft();
  }, []);

  const commitUserFacingError = useCallback((raw: string) => {
    const userMessage = getUserFacingErrorMessage(raw);
    setError(userMessage);
    setErrorCategory(classifyError(raw));
    return userMessage;
  }, []);

  const baseReportExtras = useCallback(
    () => ({
      route: pathname ?? null,
      retryCount,
      openfortUserId: openfortUserId ? openfortUserId.slice(-6) : null,
    }),
    [openfortUserId, pathname, retryCount]
  );

  const finalizeAuthenticatedSession = useCallback(
    (accessToken: string, currentUser: BackendMeResponse) => {
      closeOpenfortModal();
      setBackendAccessToken(accessToken);
      setBackendUser(currentUser);
      setPendingOnboardingAccessToken(null);
      setPendingWalletCreation(null);
      setError(null);
      setErrorCategory(null);
      clearOnboardingDraft();
      setStatus('authenticated');
    },
    [closeOpenfortModal]
  );

  // NOTE: On every login, the OpenFort SDK's useAutoRecovery hook fires in
  // the EMBEDDED_SIGNER_NOT_CONFIGURED state and attempts to recover the
  // Shield share via the Shield API.  This recovery call fails with
  // NoSecretFoundError on EVERY login (not just first login), producing
  // console errors:
  //   GET shield.openfort.io/shares/<ref>   → 400
  //   GET shield.openfort.io/shares          → 404
  //   [ERROR] failed to retrieve secret  NoSecretFoundError
  //   [ERROR] Recover failed               NoSecretFoundError
  //
  // Root cause: The iframe's recover() path calls ShieldSDK.getSecret() which
  // returns 404 — the Shield API cannot find a stored share for the user's
  // current auth context.  This appears to be a bug in the Shield / iframe
  // recovery flow (@openfort/react 1.0.12, @openfort/shield-js 0.1.36,
  // iframe v0.4.50).  See https://github.com/openfort-xyz/openfort-js/issues/272
  //
  // Impact: The wallet still functions on the same device because the iframe
  // independently recovers the private key from its own persistent storage
  // (IndexedDB in the iframe origin).  However, the useEthereumEmbeddedWallet
  // hook remains in "disconnected" state (embeddedState stays
  // NOT_CONFIGURED) until the iframe self-recovers, meaning provider is null
  // and any signing call would fail during that window.  Cross-device or
  // post-clear-storage recovery is likely broken until the upstream issue is
  // resolved.
  //
  // Current app status: No code currently calls signing methods, so the
  // errors are noise-only.  When on-chain features are added, this must be
  // re-evaluated — the provider from useEthereumEmbeddedWallet must be
  // confirmed as non-null before any signing attempt.
  const createWalletIfNeeded = useCallback(
    async (accessToken: string, currentUser: BackendMeResponse) => {
      setBackendAccessToken(accessToken);
      setBackendUser(currentUser);
      setPendingWalletCreation({ accessToken, user: currentUser });

      if (wallets.length > 0) {
        console.info('[AuthSession] Wallet already exists, skipping creation.');
        finalizeAuthenticatedSession(accessToken, currentUser);
        return;
      }

      setStatus('creating_wallet');

      try {
        await create({
          recoveryMethod: RecoveryMethod.AUTOMATIC,
        });
        finalizeAuthenticatedSession(accessToken, currentUser);
      } catch (walletError) {
        const rawMessage = getErrorMessage(walletError);
        reportError(walletError, {
          area: 'wallet',
          tags: { stage: 'create' },
          extra: {
            ...baseReportExtras(),
            hasExistingWallet: wallets.length > 0,
          },
        });
        if (/already exists|duplicate/i.test(rawMessage)) {
          console.warn(
            '[AuthSession] Possible duplicate wallet creation attempt.',
            { error: rawMessage }
          );
        }
        commitUserFacingError(rawMessage);
        setStatus('error');
      }
    },
    [
      baseReportExtras,
      commitUserFacingError,
      create,
      finalizeAuthenticatedSession,
      wallets.length,
    ]
  );

  const bootstrapSession = useCallback(async () => {
    if (!openfortUserId) {
      clearSession();
      setStatus('unauthenticated');
      return;
    }

    setStatus('loading');
    setError(null);

    try {
      const refreshedSession = await refreshBackendSession().catch(() => null);

      if (refreshedSession) {
        try {
          const me = await getBackendMe(refreshedSession.access_token);
          finalizeAuthenticatedSession(refreshedSession.access_token, me);
          return;
        } catch {
          // Refresh token was valid but user is inaccessible (e.g. soft-deleted).
          // Clear the stale cookie and fall through to Openfort re-auth.
          await logoutBackendSession().catch(() => undefined);
        }
      }

      const openfortAccessToken = await getAccessToken();

      if (!openfortAccessToken) {
        throw new Error('Openfort access token is unavailable.');
      }

      const checkResponse = await checkOpenfortUser(openfortAccessToken);

      if (!checkResponse.exists) {
        closeOpenfortModal();
        setPendingOnboardingAccessToken(openfortAccessToken);
        setStatus('needs_onboarding');
        return;
      }

      const loginResponse = await exchangeOpenfortSession(openfortAccessToken);
      const me = await getBackendMe(loginResponse.access_token);

      finalizeAuthenticatedSession(loginResponse.access_token, me);
    } catch (sessionError) {
      reportError(sessionError, {
        area: 'auth',
        tags: { stage: 'bootstrap' },
        extra: baseReportExtras(),
      });
      setBackendAccessToken(null);
      setBackendUser(null);
      setPendingOnboardingAccessToken(null);
      setPendingWalletCreation(null);
      commitUserFacingError(getErrorMessage(sessionError));
      setStatus('error');
    }
  }, [
    baseReportExtras,
    clearSession,
    closeOpenfortModal,
    commitUserFacingError,
    finalizeAuthenticatedSession,
    getAccessToken,
    openfortUserId,
  ]);

  const completeOnboarding = useCallback(
    async ({ role, type, organizationName }: QualificationSubmission) => {
      if (!pendingOnboardingAccessToken) {
        setError('Openfort access token is unavailable.');
        setStatus('error');
        return;
      }

      setStatus('loading');
      setError(null);

      try {
        const loginResponse = await exchangeOpenfortSession(
          pendingOnboardingAccessToken,
          {
            role,
            type,
            organization_name:
              type === 'organization' ? organizationName?.trim() : undefined,
          }
        );
        const me = await getBackendMe(loginResponse.access_token);

        await createWalletIfNeeded(loginResponse.access_token, me);
      } catch (sessionError) {
        reportError(sessionError, {
          area: 'auth',
          tags: { stage: 'onboarding' },
          extra: baseReportExtras(),
        });
        commitUserFacingError(getErrorMessage(sessionError));
        setStatus('needs_onboarding');
      }
    },
    [
      baseReportExtras,
      commitUserFacingError,
      createWalletIfNeeded,
      pendingOnboardingAccessToken,
    ]
  );

  const abandonOnboarding = useCallback(async () => {
    clearSession();
    setStatus('loading');

    await Promise.allSettled([
      logoutBackendSession(),
      signOut().catch(() => undefined),
    ]);

    clearSession();
    setStatus('unauthenticated');
  }, [clearSession, signOut]);

  const deleteAccount = useCallback(async () => {
    setStatus('loading');
    setError(null);

    try {
      if (backendAccessToken) {
        await deleteBackendAccount(backendAccessToken);
      }
    } catch (deleteError) {
      reportError(deleteError, {
        area: 'auth',
        tags: { stage: 'delete-account' },
        extra: baseReportExtras(),
      });
      commitUserFacingError(getErrorMessage(deleteError));
      setStatus('authenticated');
      return;
    }

    await Promise.allSettled([
      logoutBackendSession().catch(() => undefined),
      signOut().catch(() => undefined),
    ]);

    clearSession();
    setStatus('unauthenticated');
  }, [
    backendAccessToken,
    baseReportExtras,
    clearSession,
    commitUserFacingError,
    signOut,
  ]);

  const retry = useCallback(() => {
    if (pendingWalletCreation) {
      void createWalletIfNeeded(
        pendingWalletCreation.accessToken,
        pendingWalletCreation.user
      );
      return;
    }

    setRetryCount((count) => count + 1);
  }, [createWalletIfNeeded, pendingWalletCreation]);

  useEffect(() => {
    if (isLoading) {
      setStatus((currentStatus) =>
        currentStatus === 'authenticated' ||
        currentStatus === 'needs_onboarding'
          ? currentStatus
          : 'loading'
      );
      return;
    }

    if (!isAuthenticated || !openfortUserId) {
      clearSession();
      setStatus('unauthenticated');
      return;
    }

    const bootstrapAttemptKey = `${openfortUserId}:${retryCount}`;

    if (bootstrapAttemptKeyRef.current === bootstrapAttemptKey) {
      return;
    }

    bootstrapAttemptKeyRef.current = bootstrapAttemptKey;

    void bootstrapSession();
  }, [
    bootstrapSession,
    clearSession,
    isAuthenticated,
    isLoading,
    openfortUserId,
    retryCount,
  ]);

  useEffect(() => {
    const signedOut =
      previousAuthState.current && !isLoading && !isAuthenticated;

    previousAuthState.current = isAuthenticated;

    if (!signedOut) {
      return;
    }

    clearSession();
    setStatus('unauthenticated');
    void logoutBackendSession().catch(() => undefined);
  }, [clearSession, isAuthenticated, isLoading]);

  const value = useMemo<AuthSessionContextValue>(
    () => ({
      status,
      backendAccessToken,
      backendUser,
      openfortUser: user,
      isOpenfortLoading: isLoading,
      isOpenfortAuthenticated: isAuthenticated,
      error,
      errorCategory,
      retry,
      deleteAccount,
    }),
    [
      status,
      backendAccessToken,
      backendUser,
      user,
      isLoading,
      isAuthenticated,
      error,
      errorCategory,
      retry,
      deleteAccount,
    ]
  );

  return (
    <AuthSessionContext.Provider value={value}>
      {children}
      <QualificationQuestionnaire
        isOpen={status === 'needs_onboarding'}
        openfortUser={user}
        submitError={error}
        isSubmitting={status === 'loading'}
        onClose={() => {
          void abandonOnboarding();
        }}
        onSubmit={completeOnboarding}
        onDisqualifiedSuccess={abandonOnboarding}
      />
    </AuthSessionContext.Provider>
  );
}

export function useAuthSession() {
  const context = useContext(AuthSessionContext);

  if (!context) {
    throw new Error(
      'useAuthSession must be used within an AuthSessionProvider.'
    );
  }

  return context;
}

'use client';

interface BackendLoginResponse {
  user_id: string;
  access_token: string;
  expires_at: string;
}

interface BackendCheckResponse {
  exists: boolean;
}

interface BackendCountriesResponse {
  items: BackendCountryRecord[];
}

interface BackendCountryRecord {
  ID: number;
  Name: string;
  Iso: string;
  Iso3: string;
  Code: number;
  PhoneCode: number;
}

export interface CountryOption {
  id: number;
  name: string;
  iso?: string;
  iso3?: string;
  code?: number;
  phoneCode?: number;
}

interface OpenfortExchangePayload {
  first_name?: string;
  last_name?: string;
  organization_name?: string;
  phone_number?: string;
  email?: string;
  type?: 'individual' | 'organization';
  role?: string;
}

interface NonResidentIndividualPayload {
  first_name: string;
  last_name: string;
  email: string;
  country_id: number;
}

interface NonResidentCompanyPayload {
  first_name: string;
  last_name: string;
  company_name: string;
  email: string;
  country_id: number;
}

export interface BackendMeResponse {
  user_id: string;
  openfort_user_id: string;
  email: string | null;
  first_name: string | null;
  last_name: string | null;
  company_name: string | null;
  phone_number: string | null;
  type: string;
  role: string;
  status: string;
  kyc_verified: boolean;
  kyb_verified: boolean;
}

interface SuccessResponse<T> {
  code: string;
  data: T;
}

interface ErrorResponse {
  message?: string;
  detail?: string;
}

function getApiBaseUrl() {
  return (process.env.NEXT_PUBLIC_API_BASE_URL ?? '').replace(/\/+$/, '');
}

function buildUrl(path: string) {
  const normalizedPath = path.replace(/^\/+/, '');
  const baseUrl = getApiBaseUrl();

  return baseUrl ? `${baseUrl}/${normalizedPath}` : `/v1/${normalizedPath}`;
}

async function request<T>(
  path: string,
  init: RequestInit & { accessToken?: string } = {}
) {
  const headers = new Headers(init.headers);

  if (init.body && !headers.has('Content-Type')) {
    headers.set('Content-Type', 'application/json');
  }

  if (init.accessToken) {
    headers.set('Authorization', `Bearer ${init.accessToken}`);
  }

  const response = await fetch(buildUrl(path), {
    ...init,
    headers,
    credentials: 'include',
  });

  if (!response.ok) {
    let message = 'Request failed';

    try {
      const errorBody = (await response.json()) as ErrorResponse;
      message = errorBody.message || errorBody.detail || message;
    } catch {}

    throw new Error(message);
  }

  if (response.status === 204) {
    return null as T;
  }

  const body = (await response.json()) as SuccessResponse<T>;
  return body.data;
}

function normalizeCountry(country: BackendCountryRecord): CountryOption {
  return {
    id: country.ID,
    name: country.Name,
    iso: country.Iso,
    iso3: country.Iso3,
    code: country.Code,
    phoneCode: country.PhoneCode,
  };
}

export async function checkOpenfortUser(openfortAccessToken: string) {
  return request<BackendCheckResponse>('auth/openfort/check', {
    method: 'GET',
    accessToken: openfortAccessToken,
  });
}

export async function exchangeOpenfortSession(
  openfortAccessToken: string,
  body: OpenfortExchangePayload = {}
) {
  return request<BackendLoginResponse>('auth/openfort/exchange', {
    method: 'POST',
    accessToken: openfortAccessToken,
    body: JSON.stringify(body),
  });
}

export async function refreshBackendSession() {
  return request<BackendLoginResponse>('auth/refresh', {
    method: 'POST',
  });
}

export async function getBackendMe(accessToken: string) {
  return request<BackendMeResponse>('me', {
    method: 'GET',
    accessToken,
  });
}

export async function getCountries() {
  const response = await request<BackendCountriesResponse>(
    'locations/countries',
    {
      method: 'GET',
    }
  );

  return response.items
    .map(normalizeCountry)
    .filter((country) => country.id > 0 && country.name);
}

export async function submitNonResidentIndividual(
  payload: NonResidentIndividualPayload,
  captchaToken: string
) {
  await request<null>('non-resident-waitlist/individual', {
    method: 'POST',
    headers: {
      'X-Captcha-Token': captchaToken,
    },
    body: JSON.stringify(payload),
  });
}

export async function submitNonResidentCompany(
  payload: NonResidentCompanyPayload,
  captchaToken: string
) {
  await request<null>('non-resident-waitlist/company', {
    method: 'POST',
    headers: {
      'X-Captcha-Token': captchaToken,
    },
    body: JSON.stringify(payload),
  });
}

export async function logoutBackendSession() {
  await request<null>('auth/logout', {
    method: 'POST',
  });
}

export async function deleteBackendAccount(accessToken: string) {
  await request<null>('me', {
    method: 'DELETE',
    accessToken,
  });
}

import 'server-only';

type ServerEnvFeature =
  | 'database'
  | 'auth'
  | 'openfort'
  | 'captcha'
  | 'email'
  | 'shield';

interface ServerEnv {
  app: {
    environment: string;
    isProduction: boolean;
  };
  database: {
    url?: string;
  };
  auth: {
    jwtSecret?: string;
    jwtIssuer?: string;
    jwtAudience: string;
  };
  openfort: {
    secretKey?: string;
    publishableKey?: string;
    baseUrl: string;
  };
  captcha: {
    googleSecret?: string;
  };
  email: {
    enabled: boolean;
    smtpHost?: string;
    smtpPort?: string;
    smtpUser?: string;
    smtpPassword?: string;
    smtpSender?: string;
    receiver?: string;
  };
  shield: {
    url: string;
    publishableKey?: string;
    secretKey?: string;
    encryptionShare?: string;
  };
}

const requiredEnvByFeature: Record<ServerEnvFeature, string[]> = {
  database: ['DATABASE_URL'],
  auth: ['APP_JWT_SECRET'],
  openfort: ['OPENFORT_SECRET_KEY'],
  captcha: ['RECAPTCHA_SECRET_KEY'],
  email: [
    'SMTP_HOST',
    'SMTP_PORT',
    'SMTP_PASSWORD',
    'SMTP_SENDER',
    'CONTACT_FORM_RECEIVER',
  ],
  shield: [
    'NEXT_PUBLIC_SHIELD_API_KEY',
    'SHIELD_SECRET_KEY',
    'SHIELD_ENCRYPTION_SHARE',
  ],
};

let cachedEnv: ServerEnv | undefined;

function readOptionalString(name: string) {
  const value = process.env[name]?.trim();
  return value ? value : undefined;
}

function readBoolean(name: string, fallback = false) {
  const value = readOptionalString(name);

  if (!value) return fallback;

  return ['1', 'true', 'yes', 'on'].includes(value.toLowerCase());
}

export function getServerEnv() {
  if (cachedEnv) return cachedEnv;

  cachedEnv = {
    app: {
      environment:
        readOptionalString('NEXT_PUBLIC_ENVIRONMENT') ??
        readOptionalString('NODE_ENV') ??
        'development',
      isProduction: process.env.NODE_ENV === 'production',
    },
    database: {
      url: readOptionalString('DATABASE_URL'),
    },
    auth: {
      jwtSecret:
        readOptionalString('APP_JWT_SECRET') ??
        readOptionalString('JWT_SIGNING_KEY'),
      jwtIssuer: readOptionalString('APP_JWT_ISSUER'),
      jwtAudience: readOptionalString('APP_JWT_AUDIENCE') ?? 'infrafund',
    },
    openfort: {
      secretKey: readOptionalString('OPENFORT_SECRET_KEY'),
      publishableKey:
        readOptionalString('OPENFORT_PUBLISHABLE_KEY') ??
        readOptionalString('NEXT_PUBLIC_OPENFORT_PUBLIC_KEY'),
      baseUrl:
        readOptionalString('OPENFORT_BASE_URL') ?? 'https://api.openfort.io',
    },
    captcha: {
      googleSecret:
        readOptionalString('RECAPTCHA_SECRET_KEY') ??
        readOptionalString('GOOGLE_RECAPTCHA_SECRET_KEY'),
    },
    email: {
      enabled: readBoolean('CONTACT_FORM_EMAIL_ENABLED'),
      smtpHost: readOptionalString('SMTP_HOST'),
      smtpPort: readOptionalString('SMTP_PORT'),
      smtpUser: readOptionalString('SMTP_USER'),
      smtpPassword: readOptionalString('SMTP_PASSWORD'),
      smtpSender: readOptionalString('SMTP_SENDER'),
      receiver: readOptionalString('CONTACT_FORM_RECEIVER'),
    },
    shield: {
      url: readOptionalString('SHIELD_URL') ?? 'https://shield.openfort.io',
      publishableKey: readOptionalString('NEXT_PUBLIC_SHIELD_API_KEY'),
      secretKey: readOptionalString('SHIELD_SECRET_KEY'),
      encryptionShare: readOptionalString('SHIELD_ENCRYPTION_SHARE'),
    },
  };

  return cachedEnv;
}

function findMissingServerEnv(features: ServerEnvFeature[]) {
  return features.flatMap((feature) =>
    requiredEnvByFeature[feature].filter((name) => !readOptionalString(name))
  );
}

export function requireServerEnv(features: ServerEnvFeature[]) {
  const missing = findMissingServerEnv(features);

  if (missing.length > 0) {
    throw new Error(
      `Missing server environment variables: ${missing.join(', ')}`
    );
  }

  return getServerEnv();
}

import {
  AccountTypeEnum,
  ChainTypeEnum,
  type EmbeddedAccount,
  EmbeddedState,
  type Provider,
  type RecoveryParams,
  type TypedDataPayload,
} from '@openfort/openfort-js'
import axios from 'axios'
import type React from 'react'
import { createContext, useCallback, useContext, useEffect, useState } from 'react'
import { type Chain, createPublicClient, custom } from 'viem'
import type { Address } from 'viem/accounts'
import { appChain, RPC_URL } from '../utils/chainConfig'
import openfort from '../utils/openfortConfig'

const chainId = Number(process.env.NEXT_PUBLIC_CHAIN_ID)

interface ContextType {
  state: EmbeddedState
  getEvmProvider: () => Promise<Provider>
  handleRecovery: ({
    account,
    recoveryParams,
  }: {
    account: string
    recoveryParams: RecoveryParams
  }) => Promise<EmbeddedAccount>
  exportPrivateKey: () => Promise<{ data?: string; error?: Error }>
  signMessage: (
    message: string,
    options?: { hashMessage: boolean; arrayifyMessage: boolean }
  ) => Promise<{ data?: string; error?: Error }>
  signTypedData: (
    domain: TypedDataPayload['domain'],
    types: TypedDataPayload['types'],
    message: TypedDataPayload['message']
  ) => Promise<{ data?: string; error?: Error }>
  logout: () => Promise<void>
  getEOAAddress: () => Promise<string>
  getBalance: (address: Address, chain: Chain, provider: Provider) => Promise<bigint>
  account: EmbeddedAccount | null
  getEncryptionSession: (otpCode?: string) => Promise<string>
  requestOTP: (contact: { email?: string; phone?: string }, dangerouslySkipVerification: boolean) => Promise<void>
  accounts: EmbeddedAccount[]
  isLoadingAccounts: boolean
  refetchAccounts: () => Promise<void>
  refetchAccount: () => Promise<void>
  createWallet: ({ recoveryParams }: { recoveryParams: RecoveryParams }) => Promise<EmbeddedAccount>
  setRecoveryMethod: (previousRecovery: RecoveryParams, newRecovery: RecoveryParams) => Promise<void>
  getUserEmail: () => string | null
}

const OpenfortContext = createContext<ContextType | null>(null)

export function useOpenfort() {
  const context = useContext(OpenfortContext)
  if (!context) {
    throw new Error('useOpenfort must be used inside the OpenfortProvider')
  }
  return context
}

export const OpenfortProvider: React.FC<React.PropsWithChildren<unknown>> = ({ children }) => {
  const [state, setState] = useState<EmbeddedState>(EmbeddedState.NONE)

  const getEncryptionSession = async (otpCode?: string): Promise<string> => {
    try {
      const requestBody: { otp_code?: string; user_id?: any } = otpCode ? { otp_code: otpCode } : {}
      const user = await openfort.user.get()
      requestBody.user_id = user.id
      const response = await axios.post<{ session: string }>('/api/protected-create-encryption-session', requestBody, {
        headers: { 'Content-Type': 'application/json' },
        validateStatus: (status) => status < 500, // Don't throw for 4xx codes
      })

      if (response.status === 428) {
        throw new Error('OTP_REQUIRED')
      }

      return response.data.session
    } catch (error) {
      if (error instanceof Error && error.message === 'OTP_REQUIRED') {
        throw error
      }
      throw new Error(`Failed to create encryption session: ${error}`)
    }
  }

  const requestOTP = async (
    contact: { email?: string; phone?: string },
    dangerouslySkipVerification: boolean
  ): Promise<void> => {
    console.log(
      'requestOTP function called with contact:',
      contact,
      'dangerouslySkipVerification:',
      dangerouslySkipVerification
    )
    try {
      const user = await openfort.user.get()

      if (!user) throw new Error('User not found')

      if ((!contact.email && !contact.phone) || (contact.email && contact.phone)) {
        throw new Error('Please provide either email or phone number, not both')
      }

      const response = await axios.post(
        '/api/request-otp',
        {
          user_id: user.id,
          email: contact.email || null,
          phone: contact.phone || null,
        },
        {
          headers: { 'Content-Type': 'application/json' },
          validateStatus: (status) => status < 500, // Don't throw for 4xx codes
        }
      )

      if (response.data.error === 'OTP_RATE_LIMIT') {
        throw new Error(response.data.error)
      } else if (response.data.error === 'USER_CONTACTS_MISMATCH') {
        throw new Error(response.data.error)
      } else if (response.status !== 200) {
        throw new Error(`OTP request failed with status: ${response.status}`)
      }

      // Success - API returns 200 with empty body
    } catch (error) {
      console.error('Error in requestOTP:', error)
      throw error
    }
  }

  useEffect(() => {
    const unwatch = openfort.embeddedWallet.watchEmbeddedState({
      onChange: (currentState: EmbeddedState) => setState(currentState),
      onError: (err: Error) => console.error('Error watching embedded state:', err),
      pollingInterval: 300,
    })
    return unwatch
  }, [])

  // Account
  const [account, setAccount] = useState<EmbeddedAccount | null>(null)
  const [accounts, setAccounts] = useState<EmbeddedAccount[]>([])
  const [isLoadingAccounts, setIsLoadingAccounts] = useState(false)

  const refetchAccount = useCallback(async () => {
    const account = await openfort.embeddedWallet.get()
    setAccount(account)
  }, [])

  const refetchAccounts = useCallback(async () => {
    setIsLoadingAccounts(true)
    const accounts = await openfort.embeddedWallet.list({
      chainId: chainId,
    })
    setAccounts(accounts)
    setIsLoadingAccounts(false)
  }, [])

  useEffect(() => {
    if (state === EmbeddedState.EMBEDDED_SIGNER_NOT_CONFIGURED) {
      setAccount(null)
      refetchAccounts()
    } else if (state === EmbeddedState.READY) {
      refetchAccount()
      refetchAccounts()
    } else if (state === EmbeddedState.UNAUTHENTICATED) {
      setAccount(null)
      setAccounts([])
    }
  }, [state, refetchAccount, refetchAccounts])

  const getEvmProvider = useCallback(async (): Promise<Provider> => {
    const externalProvider = await openfort.embeddedWallet.getEthereumProvider({
      feeSponsorship: process.env.NEXT_PUBLIC_POLICY_ID,
      chains: {
        [appChain.id]: RPC_URL,
      },
    })
    if (!externalProvider) {
      throw new Error('EVM provider is undefined')
    }
    return externalProvider as Provider
  }, [])

  const signMessage = useCallback(
    async (
      message: string,
      options?: { hashMessage: boolean; arrayifyMessage: boolean }
    ): Promise<{ data?: string; error?: Error }> => {
      try {
        const data = await openfort.embeddedWallet.signMessage(message, options)
        return { data }
      } catch (err) {
        console.error('Error signing message:', err)
        return {
          error: err instanceof Error ? err : new Error('An error occurred signing the message'),
        }
      }
    },
    []
  )

  const exportPrivateKey = useCallback(async (): Promise<{
    data?: string
    error?: Error
  }> => {
    try {
      const data = await openfort.embeddedWallet.exportPrivateKey()
      return { data }
    } catch (err) {
      console.error('Error exporting private key:', err)
      return {
        error: err instanceof Error ? err : new Error('An error occurred exporting the private key'),
      }
    }
  }, [])

  const signTypedData = useCallback(
    async (
      domain: TypedDataPayload['domain'],
      types: TypedDataPayload['types'],
      message: TypedDataPayload['message']
    ): Promise<{ data?: string; error?: Error }> => {
      try {
        const data = await openfort.embeddedWallet.signTypedData(domain, types, message)
        return { data }
      } catch (err) {
        console.error('Error signing typed data:', err)
        return {
          error: err instanceof Error ? err : new Error('An error occurred signing the typed data'),
        }
      }
    },
    []
  )

  const handleRecovery = useCallback(
    async ({ account, recoveryParams }: { account: string; recoveryParams: RecoveryParams }) => {
      const response = await openfort.embeddedWallet.recover({
        recoveryParams,
        account,
      })
      refetchAccounts()
      setAccount(response)
      return response
    },
    [refetchAccounts]
  )

  const logout = useCallback(async () => {
    try {
      await openfort.auth.logout()
      if (typeof window !== 'undefined') {
        localStorage.removeItem('userEmail')
      }
    } catch (err) {
      console.error('Error logging out with Openfort:', err)
      throw err instanceof Error ? err : new Error('An error occurred during logout')
    }
  }, [])

  const getEOAAddress = useCallback(async () => {
    try {
      const account = await openfort.embeddedWallet.get()
      return account.ownerAddress as `0x${string}`
    } catch (err) {
      console.error('Error obtaining EOA Address with Openfort:', err)
      throw err instanceof Error ? err : new Error('An error occurred obtaining the EOA Address')
    }
  }, [])

  const getBalance = useCallback(async (address: Address, chain: Chain, provider: Provider) => {
    try {
      const publicClient = createPublicClient({
        chain,
        transport: custom(provider),
      })
      return await publicClient.getBalance({ address })
    } catch (err) {
      console.error('Error obtaining Wallet Balance with Openfort:', err)
      throw err instanceof Error ? err : new Error('An error occurred obtaining the Wallet Balance')
    }
  }, [])

  const createWallet = useCallback(
    async ({ recoveryParams }: { recoveryParams: RecoveryParams }) => {
      const user = await openfort.user.get()
      if (!user) throw new Error('User not found')

      if (user.email === 'testing@fort.dev') {
        throw new Error('Test user should not create wallets.')
      }

      const response = await openfort.embeddedWallet.create({
        accountType: AccountTypeEnum.SMART_ACCOUNT,
        chainType: ChainTypeEnum.EVM,
        recoveryParams,
        chainId,
      })
      setAccount(response)
      await refetchAccounts()
      return response
    },
    [refetchAccounts]
  )

  const setRecoveryMethod = useCallback(
    async (previousRecovery: RecoveryParams, newRecovery: RecoveryParams) => {
      await openfort.embeddedWallet.setRecoveryMethod(previousRecovery, newRecovery)
      await refetchAccount()
      await refetchAccounts()
    },
    [refetchAccount, refetchAccounts]
  )

  const getUserEmail = useCallback((): string | null => {
    if (typeof window !== 'undefined') {
      return localStorage.getItem('userEmail')
    }
    return null
  }, [])

  const contextValue: ContextType = {
    state,
    getEncryptionSession,
    requestOTP,
    getEvmProvider,
    handleRecovery,
    signMessage,
    exportPrivateKey,
    signTypedData,
    logout,
    getEOAAddress,
    getBalance,
    account,
    refetchAccount,
    accounts,
    isLoadingAccounts,
    refetchAccounts,
    createWallet,
    setRecoveryMethod,
    getUserEmail,
  }

  return <OpenfortContext.Provider value={contextValue}>{children}</OpenfortContext.Provider>
}

