 */
export interface OpenfortOptions {
  /** API base URL (optional) */
  basePath?: string
  /** Wallet secret for X-Wallet-Auth header (optional) */
  walletSecret?: string
  /** Enable debug logging (optional) */
  debugging?: boolean
