    secure: process.env.NODE_ENV === 'production',
    sameSite: normalizeSameSite(authConfig.cookieSameSite),
    ...(authConfig.cookieDomain ? { domain: authConfig.cookieDomain } : {}),
  });
}

import 'server-only';

import Openfort from '@openfort/openfort-node';

import { ApiError } from '@/server/http';
import { logger } from '@/server/logger';
import { requireServerEnv } from '@/server/env';

export interface VerifiedOpenfortSession {
  user: {
    id: string;
    email?: string | null;
    name?: string | null;
    phoneNumber?: string | null;
  };
  session: {
    id?: string | null;
    expiresAt?: string | null;
  };
}

let cachedClient: Openfort | undefined;

function getOpenfortClient() {
  if (cachedClient) return cachedClient;

  const { openfort } = requireServerEnv(['openfort']);
  cachedClient = new Openfort(openfort.secretKey!, {
    basePath: openfort.baseUrl,
    publishableKey: openfort.publishableKey,
  });

  return cachedClient;
}

function normalizeOpenfortSession(session: unknown): VerifiedOpenfortSession {
  if (!session || typeof session !== 'object') {
    throw new ApiError('UNAUTHORIZED', 'Invalid Openfort access token.');
  }

  const value = session as {
    user?: {
      id?: unknown;
      email?: unknown;
      name?: unknown;
      phoneNumber?: unknown;
    };
    session?: {
      id?: unknown;
      expiresAt?: unknown;
    };
  };
  const userId = value.user?.id;

  if (typeof userId !== 'string' || !userId.trim()) {
    throw new ApiError('UNAUTHORIZED', 'Invalid Openfort access token.');
  }

  return {
    user: {
      id: userId,
      email:
        typeof value.user?.email === 'string' ? value.user.email : undefined,
      name: typeof value.user?.name === 'string' ? value.user.name : undefined,
      phoneNumber:
        typeof value.user?.phoneNumber === 'string'
          ? value.user.phoneNumber
          : undefined,
    },
    session: {
      id: typeof value.session?.id === 'string' ? value.session.id : undefined,
      expiresAt:
        typeof value.session?.expiresAt === 'string'
          ? value.session.expiresAt
          : undefined,
    },
  };
}

export async function verifyOpenfortAccessToken(accessToken: string) {
  try {
    const session = await getOpenfortClient().iam.getSession({ accessToken });
    return normalizeOpenfortSession(session);
  } catch (error) {
    if (error instanceof ApiError) throw error;

    logger.warn({ err: error }, 'Openfort session verification failed');
    throw new ApiError('UNAUTHORIZED', 'Invalid Openfort access token.');
  }
}

import 'server-only';

import type { RequestMetadata } from '@/server/http';
import { ApiError } from '@/server/http';
import { getAuthConfig } from '@/server/auth/config';
import { signAppAccessToken } from '@/server/auth/jwt';
import { createOpaqueToken, hashOpaqueToken } from '@/server/auth/tokens';
import { createSession } from '@/server/repositories/sessions';
import {
  createUser,
  findUserByOpenfortId,
  isUserUniqueConstraintError,
  openfortUserExists,
  type CreateUserRecord,
} from '@/server/repositories/users';
import {
  verifyOpenfortAccessToken,
  type VerifiedOpenfortSession,
} from '@/server/openfort/session';

interface OpenfortExchangeInput {
  accessToken: string;
  firstName?: string;
  lastName?: string;
  organizationName?: string;
  phoneNumber?: string;
  email?: string;
  type?: string;
  role?: string;
  metadata: RequestMetadata;
}

function emptyToNull(value: string | null | undefined) {
  const trimmed = value?.trim();
  return trimmed ? trimmed : null;
}

function splitName(name: string | undefined | null) {
  const parts = name?.trim().split(/\s+/).filter(Boolean) ?? [];

  if (parts.length === 0) return { firstName: null, lastName: null };
  if (parts.length === 1) return { firstName: parts[0], lastName: null };

  return {
    firstName: parts[0],
    lastName: parts.slice(1).join(' '),
  };
}

function normalizeUserType(type: string | undefined): CreateUserRecord['type'] {
  return type === 'organization' ? 'organization' : 'individual';
}

function normalizeUserRole(role: string | undefined): CreateUserRecord['role'] {
  switch (role) {
    case 'project_owner':
    case 'investor':
    case 'contractor':
    case 'governance':
      return role;
    case 'client':
      return 'project_owner';
    case 'dao':
      return 'governance';
    default:
      return 'investor';
  }
}

function assertNewUserPayload(input: OpenfortExchangeInput) {
  if (!input.type) {
    throw new ApiError('BAD_REQUEST', 'User type is required for new users.');
  }

  if (!input.role) {
    throw new ApiError('BAD_REQUEST', 'User role is required for new users.');
  }

  if (input.type === 'organization' && !emptyToNull(input.organizationName)) {
    throw new ApiError('BAD_REQUEST', 'Organization name is required.');
  }
}

function buildUserRecord(
  input: OpenfortExchangeInput,
  session: VerifiedOpenfortSession
): CreateUserRecord {
  const sessionName = splitName(session.user.name);

  return {
    openfortUserId: session.user.id,
    email: emptyToNull(input.email) ?? emptyToNull(session.user.email),
    firstName: emptyToNull(input.firstName) ?? sessionName.firstName,
    lastName: emptyToNull(input.lastName) ?? sessionName.lastName,
    phoneNumber:
      emptyToNull(input.phoneNumber) ?? emptyToNull(session.user.phoneNumber),
    companyName: emptyToNull(input.organizationName),
    type: normalizeUserType(input.type),
    role: normalizeUserRole(input.role),
  };
}

async function findOrCreateUser(
  input: OpenfortExchangeInput,
  session: VerifiedOpenfortSession
) {
  const existingUser = await findUserByOpenfortId(session.user.id);

  if (existingUser) {
    return existingUser;
  }

  assertNewUserPayload(input);

  try {
    return await createUser(buildUserRecord(input, session));
  } catch (error) {
    if (isUserUniqueConstraintError(error)) {
      throw new ApiError('CONFLICT', 'User already exists, please try again.');
    }

    throw error;
  }
}

export async function checkOpenfortUser(accessToken: string) {
  const session = await verifyOpenfortAccessToken(accessToken);

  return {
    exists: await openfortUserExists(session.user.id),
  };
}

export async function exchangeOpenfortSession(input: OpenfortExchangeInput) {
  const openfortSession = await verifyOpenfortAccessToken(input.accessToken);
  const user = await findOrCreateUser(input, openfortSession);
  const refreshToken = createOpaqueToken();
  const authConfig = getAuthConfig();
  const now = Date.now();
  const accessTokenExpiresAt = new Date(now + authConfig.accessTokenTtlMs);
  const session = await createSession({
    userId: user.id,
    refreshTokenHash: hashOpaqueToken(refreshToken),
    metadata: input.metadata,
    activityTimeoutAt: new Date(now + authConfig.activityTimeoutMs),
    absoluteExpiresAt: new Date(now + authConfig.absoluteSessionTtlMs),
  });
  const accessToken = await signAppAccessToken(
    {
      userId: user.id,
      sessionId: session.id,
      kycVerified: Boolean(user.kycVerified),
      kybVerified: Boolean(user.kybVerified),
      type: user.type,
      role: user.role,
    },
    accessTokenExpiresAt
  );

  return {
    userId: user.id,
    accessToken,
    accessTokenExpiresAt,
    refreshToken,
    refreshTokenExpiresAt: new Date(now + authConfig.absoluteSessionTtlMs),
  };
}

import 'server-only';

import type { UserRole, UserType } from '@prisma/client';
import { SignJWT } from 'jose';

import { requireServerEnv } from '@/server/env';

interface AppAccessTokenClaims {
  userId: string;
  sessionId: string;
  kycVerified: boolean;
  kybVerified: boolean;
  type: UserType;
  role: UserRole;
}

function getJwtSecret() {
  const env = requireServerEnv(['auth']);
  return new TextEncoder().encode(env.auth.jwtSecret!);
}

export async function signAppAccessToken(
  claims: AppAccessTokenClaims,
  expiresAt: Date
) {
  const env = requireServerEnv(['auth']);
  const jwt = new SignJWT({
    session_id: claims.sessionId,
    kyc_verified: claims.kycVerified,
    kyb_verified: claims.kybVerified,
    type: claims.type,
    role: claims.role,
  })
    .setProtectedHeader({ alg: 'HS256' })
    .setSubject(claims.userId)
    .setAudience(env.auth.jwtAudience)
    .setIssuedAt()
    .setExpirationTime(Math.floor(expiresAt.getTime() / 1000));

  if (env.auth.jwtIssuer) {
    jwt.setIssuer(env.auth.jwtIssuer);
  }

  return jwt.sign(getJwtSecret());
}

import 'server-only';

import { createHash, randomBytes } from 'node:crypto';

export function createOpaqueToken() {
  return randomBytes(32).toString('base64url');
}

export function hashOpaqueToken(token: string) {
  return new Uint8Array(createHash('sha256').update(token, 'utf8').digest());
}

import 'server-only';

import { ApiError } from '@/server/http';

export function requireBearerToken(request: Request) {
  const authorization = request.headers.get('authorization') ?? '';
  const prefix = 'Bearer ';

  if (!authorization.startsWith(prefix)) {
    throw new ApiError(
      'BAD_REQUEST',
      'Authorization bearer token is required.'
    );
  }

  const token = authorization.slice(prefix.length).trim();

  if (!token) {
    throw new ApiError(
      'BAD_REQUEST',
      'Authorization bearer token is required.'
    );
  }

  return token;
}

import 'server-only';

import type { RequestMetadata } from '@/server/http';
import { getDb } from '@/server/db';

interface CreateSessionRecord {
  userId: string;
  refreshTokenHash: Uint8Array<ArrayBuffer>;
  metadata: RequestMetadata;
  activityTimeoutAt: Date;
  absoluteExpiresAt: Date;
}

export function createSession(record: CreateSessionRecord) {
  const now = new Date();

  return getDb().session.create({
    data: {
      userId: record.userId,
      refreshTokenHash: record.refreshTokenHash,
      userAgent: record.metadata.userAgent,
      ipAddress: record.metadata.ipAddress,
      platform: record.metadata.platform,
      browser: record.metadata.browser,
      device: record.metadata.device,
      createdAt: now,
      lastActivityAt: now,
      activityTimeoutAt: record.activityTimeoutAt,
      absoluteExpiresAt: record.absoluteExpiresAt,
    },
  });
}

import 'server-only';

import { Prisma, type UserRole, type UserType } from '@prisma/client';

import { getDb } from '@/server/db';

export interface CreateUserRecord {
  openfortUserId: string;
  email?: string | null;
  firstName?: string | null;
  lastName?: string | null;
  phoneNumber?: string | null;
  companyName?: string | null;
  type: UserType;
  role: UserRole;
}

export function findUserByOpenfortId(openfortUserId: string) {
  return getDb().user.findFirst({
    where: {
      openfortUserId,
      deletedAt: null,
    },
  });
}

export async function openfortUserExists(openfortUserId: string) {
  const count = await getDb().user.count({
    where: {
      openfortUserId,
      deletedAt: null,
    },
  });

  return count > 0;
}

export async function createUser(record: CreateUserRecord) {
  return getDb().$transaction(async (tx) => {
    const user = await tx.user.create({
      data: {
        openfortUserId: record.openfortUserId,
        email: record.email,
        firstName: record.firstName,
        lastName: record.lastName,
        phoneNumber: record.phoneNumber,
        type: record.type,
        role: record.role,
        status: 'pending_kyc',
      },
    });

    if (record.type === 'organization' && record.companyName) {
      await tx.userOrganization.create({
        data: {
          userId: user.id,
          name: record.companyName,
        },
      });
    }

    return user;
  });
}

export function isUserUniqueConstraintError(error: unknown) {
  return (
    error instanceof Prisma.PrismaClientKnownRequestError &&
    error.code === 'P2002'
  );
}

